async function runSingleChargeMode(): Promise<void> {
  console.log('='.repeat(80))
  console.log('OpenNode Payment Recovery Script')
  console.log('='.repeat(80))

  if (dryRun) {
    console.log('🔍 DRY RUN MODE - No changes will be made')
    console.log()
  }

  // Step 1: Find the OpenNode charge
  console.log('Step 1: Finding OpenNode charge...')
  let charge: OpenNodeCharge | null = null

  if (chargeId) {
    charge = await prisma.openNodeCharge.findUnique({
      where: { openNodeChargeId: chargeId },
    })
    if (charge) {
      invoiceId = charge.stripeInvoiceId
    }
  } else if (invoiceId) {
    charge = await prisma.openNodeCharge.findUnique({
      where: { stripeInvoiceId: invoiceId },
    })
    if (charge) {
      chargeId = charge.openNodeChargeId
    }
  }

  if (!charge) {
    console.error('❌ OpenNode charge not found')
    if (chargeId) {
      console.error(`   Charge ID: ${chargeId}`)
    }
    if (invoiceId) {
      console.error(`   Invoice ID: ${invoiceId}`)
    }
    process.exit(1)
  }

  console.log('✅ OpenNode charge found')
  console.log(`   Charge ID: ${charge.openNodeChargeId}`)
  console.log(`   Invoice ID: ${charge.stripeInvoiceId}`)
  console.log(`   User ID: ${charge.userId}`)
  console.log(`   Status: ${charge.status}`)
  console.log(`   Amount: ${charge.amount} ${charge.currency.toUpperCase()}`)
  console.log(`   Last Webhook At: ${charge.lastWebhookAt || 'NULL'}`)
  console.log()

  // Step 2: Validate charge status
  console.log('Step 2: Validating charge status...')
  if (charge.status !== 'paid' && charge.status !== 'confirmed') {
    console.error(`❌ Charge status is '${charge.status}', expected 'paid' or 'confirmed'`)
    console.error('   Cannot process payment that has not been confirmed by OpenNode')
    process.exit(1)
  }
  console.log(`✅ Charge status is '${charge.status}'`)
  console.log()

  // Step 3: Check for existing lifetime subscription
  console.log('Step 3: Checking for existing subscription...')
  const existingSubscription = await prisma.subscription.findFirst({
    where: {
      status: SubscriptionStatus.ACTIVE,
      transactionType: TransactionType.LIFETIME,
      userId: charge.userId,
    },
  })

  if (existingSubscription) {
    console.log('⚠️  User already has an active lifetime subscription')
    console.log(`   Subscription ID: ${existingSubscription.id}`)
    console.log(`   Created At: ${existingSubscription.createdAt}`)
    console.log(`   Period End: ${existingSubscription.currentPeriodEnd}`)
    console.log()
    console.log('✅ Payment has already been processed successfully')

    // Update lastWebhookAt if it's NULL
    if (!charge.lastWebhookAt && !dryRun) {
      console.log('Updating OpenNode charge lastWebhookAt...')
      await prisma.openNodeCharge.update({
        data: {
          lastWebhookAt: new Date(),
          metadata: {
            ...(charge.metadata as Record<string, unknown>),
            recoveryNote: 'Subscription already existed, just updated lastWebhookAt',
            recoveryScriptRan: true,
            recoveryScriptRunAt: new Date().toISOString(),
          },
        },
        where: { openNodeChargeId: charge.openNodeChargeId },
      })
      console.log('✅ Updated OpenNode charge record')
    }

    process.exit(0)
  }
  console.log('✅ No existing lifetime subscription found')
  console.log()

  // Step 4: Retrieve Stripe invoice
  console.log('Step 4: Retrieving Stripe invoice...')
  const invoice = await stripe.invoices.retrieve(charge.stripeInvoiceId)

  console.log('✅ Stripe invoice retrieved')
  console.log(`   Invoice ID: ${invoice.id}`)
  console.log(`   Status: ${invoice.status}`)
  console.log(`   Customer ID: ${invoice.customer}`)
  console.log('   Metadata:')
  console.log(`     - userId: ${invoice.metadata?.userId || 'N/A'}`)
  console.log(`     - stripePriceId: ${invoice.metadata?.stripePriceId || 'N/A'}`)
  console.log(`     - paymentProvider: ${invoice.metadata?.paymentProvider || 'N/A'}`)
  console.log(`     - isCryptoPayment: ${invoice.metadata?.isCryptoPayment || 'N/A'}`)
  console.log()

  // Step 5: Validate invoice metadata
  console.log('Step 5: Validating invoice metadata...')
  if (!invoice.metadata?.userId) {
    console.error('❌ Invoice is missing userId in metadata')
    process.exit(1)
  }
  if (!invoice.metadata?.stripePriceId) {
    console.error('❌ Invoice is missing stripePriceId in metadata')
    process.exit(1)
  }
  if (invoice.metadata?.paymentProvider !== 'opennode') {
    console.warn(
      `⚠️  Invoice paymentProvider is '${invoice.metadata?.paymentProvider}', expected 'opennode'`,
    )
  }
  console.log('✅ Invoice metadata is valid')
  console.log()

  if (dryRun) {
    console.log('='.repeat(80))
    console.log('DRY RUN COMPLETE')
    console.log('='.repeat(80))
    console.log('✅ All validations passed')
    console.log()
    console.log('Next steps if run without --dry-run:')
    console.log('  1. Mark Stripe invoice as paid (out-of-band)')
    console.log('  2. Process invoice.paid event via handleInvoiceEvent()')
    console.log('  3. Create lifetime subscription in database')
    console.log('  4. Update OpenNode charge lastWebhookAt')
    console.log('  5. Verify subscription was created')
    console.log()
    process.exit(0)
  }

  // Step 6: Mark Stripe invoice as paid
  console.log('Step 6: Marking Stripe invoice as paid...')
  if (!invoice.id) {
    console.error('❌ Invoice is missing id')
    process.exit(1)
  }
  const singleInvoiceId = invoice.id
  if (invoice.status === 'paid') {
    console.log('⚠️  Invoice is already marked as paid in Stripe')
  } else {
    try {
      await stripe.invoices.pay(
        singleInvoiceId,
        { paid_out_of_band: true },
        { idempotencyKey: charge.openNodeChargeId },
      )
      console.log('✅ Marked Stripe invoice as paid (out-of-band)')
    } catch (error: unknown) {
      if (error instanceof Error && 'code' in error && error.code === 'invoice_already_paid') {
        console.log('⚠️  Invoice is already paid (Stripe API confirmed)')
      } else {
        throw error
      }
    }
  }
  console.log()

  // Step 7: Process the invoice event (creates subscription)
  console.log('Step 7: Processing invoice.paid event...')
  console.log('Creating subscription via handleInvoiceEvent...')

  const result = await prisma.$transaction(async (tx) => {
    // Re-fetch invoice to get the latest status
    const updatedInvoice = await stripe.invoices.retrieve(singleInvoiceId)
    const success = await handleInvoiceEvent(updatedInvoice, tx)
    return success
  })

  if (!result) {
    console.error('❌ Failed to create subscription via handleInvoiceEvent')
    console.error('   Check the logs above for error details')
    process.exit(1)
  }
  console.log('✅ Successfully processed invoice event')
  console.log()

  // Step 8: Verify subscription was created
  console.log('Step 8: Verifying subscription creation...')
  const subscription = await prisma.subscription.findFirst({
    where: {
      status: SubscriptionStatus.ACTIVE,
      transactionType: TransactionType.LIFETIME,
      userId: charge.userId,
    },
  })

  if (!subscription) {
    console.error('❌ Subscription was not created')
    console.error('   Expected to find a LIFETIME subscription but none exists')
    process.exit(1)
  }

  console.log('✅ Subscription created successfully')
  console.log(`   Subscription ID: ${subscription.id}`)
  console.log(`   User ID: ${subscription.userId}`)
  console.log(`   Transaction Type: ${subscription.transactionType}`)
  console.log(`   Status: ${subscription.status}`)
  console.log(`   Tier: ${subscription.tier}`)
  console.log(`   Current Period End: ${subscription.currentPeriodEnd}`)
  console.log()

  // Step 9: Update OpenNode charge record
  console.log('Step 9: Updating OpenNode charge record...')
  await prisma.openNodeCharge.update({
    data: {
      lastWebhookAt: new Date(),
      metadata: {
        ...(charge.metadata as Record<string, unknown>),
        processedSuccessfully: true,
        recoveryScriptRan: true,
        recoveryScriptRunAt: new Date().toISOString(),
        subscriptionId: subscription.id,
      },
    },
    where: { openNodeChargeId: charge.openNodeChargeId },
  })
  console.log('✅ Updated OpenNode charge record with lastWebhookAt')
  console.log()

  // Final summary
  console.log('='.repeat(80))
  console.log('RECOVERY COMPLETE')
  console.log('='.repeat(80))
  console.log('✅ Payment processing completed successfully')
  console.log()
  console.log('Summary:')
  console.log(`  • OpenNode Charge ID: ${charge.openNodeChargeId}`)
  console.log(`  • Stripe Invoice ID: ${charge.stripeInvoiceId}`)
  console.log(`  • User ID: ${charge.userId}`)
  console.log(`  • Subscription ID: ${subscription.id}`)
  console.log(`  • Subscription Type: ${subscription.transactionType}`)
  console.log(`  • Subscription Status: ${subscription.status}`)
  console.log()
  console.log('The user now has access to PRO features.')
  console.log()
}

{
  const router = useRouter()
  const { notification } = App.useApp()
  const { data: isDotabodDisabled } = useUpdateSetting(Settings.commandDisable)
  const { original, error, mutate: refreshSettings } = useUpdateSetting()
  const { height, width } = useWindowSize()
  const [connected, setConnected] = useState(false)
  const [showDevImage, setShowDevImage] = useState(true)
  const [showMainScreenOverlay, setShowMainScreenOverlay] = useState(false)
  const [hasShownOnce, setHasShownOnce] = useState(false)
  const reportedErrorStatus = useRef<number | null>(null)

  useEffect(() => {
    const userId = typeof router.query.userId === 'string' ? router.query.userId : null
    if (!userId || typeof window.obsstudio !== 'object') {
      return
    }

    const reportPageLoaded = () => {
      fetch('/api/diagnostics/overlay-page', {
        body: JSON.stringify({ userId }),
        headers: { 'Content-Type': 'application/json' },
        keepalive: true,
        method: 'POST',
      }).catch(() => {})
    }

    reportPageLoaded()
    const interval = window.setInterval(reportPageLoaded, 60_000)
    return () => {
      window.clearInterval(interval)
    }
  }, [router.query.userId])

  const [block, setBlock] = useState<blockType>({
    matchId: null,
    team: null,
    type: null,
  })
  const [pollData, setPollData] = useState<PollData | null>(null)
  const [betData, setBetData] = useState<{
    title: string
    endDate: PollData['endDate']
    outcomes: { title: string; totalVotes: number; channelPoints: number }[]
  } | null>(null)
  const [paused, setPaused] = useState(false)
  const { roshan, setRoshan } = useRoshan()
  const { aegis, setAegis } = useAegis()
  const { notablePlayers, setNotablePlayers } = useNotablePlayers()
  const [wl, setWL] = useState<wlType>({
    records: [{ lose: 0, type: 'U', win: 0 }],
    statsDays: null,
  })
  const [radiantWinChance, setRadiantWinChance] = useState<WinChance | null>(null)

  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([])

  const [rankImageDetails, setRankImageDetails] = useState<{
    image: string | null
    rank: number | null
    leaderboard: number | null
    notLoaded?: boolean
  }>({
    image: '0.png',
    leaderboard: 0,
    notLoaded: true,
    rank: 0,
  })

  const [isInIframe, setIsInIframe] = useState(false)
  const isDevMode = useIsDevMode()
  const is404 = error && typeof error === 'object' && 'status' in error && error.status === 404

  // Add detection for OBS environment
  const [isOldObs, setIsOldObs] = useState(false)
  useEffect(() => {
    // Check if running in OBS (older Chromium)
    const isOldOBS =
      // New OBS uses browser source/docks CEF (Chromium) version 127 (6533)
      // Check if we're running in an older version that needs compatibility
      Number.parseInt(/Chrome\/(\d+)/u.exec(navigator.userAgent)?.[1] || '999', 10) < 127

    setIsOldObs(isOldOBS)
  }, [])

  // Wait 10s after the first connect before showing MainScreenOverlays;
  // Reconnects after that show immediately.
  useEffect(() => {
    if (!connected) {
      return
    }
    if (hasShownOnce) {
      setShowMainScreenOverlay(true)
      return
    }
    const timer = setTimeout(() => {
      setShowMainScreenOverlay(true)
      setHasShownOnce(true)
    }, 10_000)
    return () => {
      clearTimeout(timer)
    }
  }, [connected, hasShownOnce])

  useEffect(() => {
    if (!original) {
      return
    }

    const steamAccount = original.SteamAccount?.[0]
    const rank = getRankDetail(
      steamAccount?.mmr ?? original.mmr ?? 0,
      steamAccount?.leaderboard_rank ?? null,
    )

    if (!rank) {
      return
    }

    const leaderboard =
      'standing' in rank ? rank.standing : (steamAccount?.leaderboard_rank ?? null)

    const rankDetails: {
      image: string
      rank: number
      leaderboard: number | null
      notLoaded: boolean
    } = {
      image: rank.myRank?.image ?? '0.png',
      leaderboard,
      notLoaded: false,
      rank: rank.mmr,
    }

    setRankImageDetails(rankDetails)
  }, [original])

  useStreamOfflineNotification(original?.stream_online, notification, refreshSettings)

  useEffect(() => {
    setIsInIframe(window.self !== window.top)
  }, [])

  useEffect(() => {
    if (error && !is404) {
      const status = (error as PotentialError)?.status
      // Skip transient network errors (no status -> SWR will retry) and 5xx
      // (already captured server-side in /api/settings). Report each status once.
      const isReportable = typeof status === 'number' && status < 500 && status !== 404
      if (isReportable && reportedErrorStatus.current !== status) {
        reportedErrorStatus.current = status
        Sentry.captureException(new Error('Error in overlay page fetching settings'), {
          extra: {
            message: (error as PotentialError)?.message,
            status,
          },
        })
      }
    } else {
      reportedErrorStatus.current = null
    }

    if (is404) {
      // For 404 errors, add local storage cache to prevent repeated API calls
      if (typeof window !== 'undefined' && window.localStorage) {
        try {
          // Store the invalid URL in local storage with timestamp
          const pathKey = `invalid_overlay_${window.location.pathname}`
          localStorage.setItem(
            pathKey,
            JSON.stringify({
              status: 404,
              timestamp: Date.now(),
            }),
          )
        } catch {
          // Ignore storage errors
        }
      }

      notification.open({
        description: 'Please delete your overlay and setup Dotabod again by visiting dotabod.com',
        duration: 0,
        key: 'auth-error',
        message: 'Authentication failed',
        placement: 'bottomLeft',
        type: 'error',
      })
    } else {
      notification.destroy('auth-error')
    }
  }, [error, notification, is404])

  useEffect(() => {
    if (!isDevMode) {
      return
    }
    setWL(devWL)
    setPollData(devPoll)
    setBlock(devBlockTypes)
    setRankImageDetails(devRank)
    setRadiantWinChance(devRadiantWinChance)
  }, [isDevMode])

  useSocket({
    setAegis,
    setBetData,
    setBlock,
    setChatMessages,
    setConnected,
    setNotablePlayers,
    setPaused,
    setPollData,
    setRadiantWinChance,
    setRankImageDetails,
    setRoshan,
    setWL,
  })

  useOBS({ block, connected })

  // This specific check might become redundant if _app.tsx handles it robustly.
  if (isInvalidLocalCheck) {
    return <InvalidOverlayPage />
  }

  if (is404) {
    // Return minimal content for 404s to reduce resource usage
    // This helps when users mistype URLs or accounts are deleted
    return (
      <>
        {/* oxlint-disable-next-line nextjs/no-duplicate-head -- conditional render path, only one Head per render */}
        <Head>
          <title>Dotabod | Invalid Overlay URL</title>
          <meta name='robots' content='noindex' />
        </Head>
        <style global jsx>{`
          html,
          body {
            overflow: hidden;
            background-color: transparent;
          }
        `}</style>
        <div className='hidden'>Invalid Dotabod overlay URL. Please check your OBS settings.</div>
      </>
    )
  }

  if (isDotabodDisabled) {
    return isDevMode ? (
      <>
        <motion.div
          className={clsx('absolute right-0 mt-9 block max-w-xs')}
          key='not-live'
          {...motionProps}
        >
          <Alert message='Dotabod is disabled!' />
        </motion.div>
        <Image
          key='dev-image'
          width={width}
          height={height}
          alt={`${block.type} dev screenshot`}
          src={`/images/dev/${width && height && Math.round((width / height) * 9) === 21 ? '21-9-' : ''}${block.type === 'spectator' ? 'playing' : (block.type ?? 'main-menu')}.png`}
        />
      </>
    ) : null
  }

  // Main overlay content for valid users
  return (
    <>
      <Head>
        <title>Dotabod | Stream overlays</title>
        {/* oxlint-disable-next-line nextjs/no-css-tags -- OBS legacy compatibility stylesheet */}
        {isOldObs && <link rel='stylesheet' href='/styles/obs-compat.css' />}
      </Head>
      <style global jsx>{`
        html,
        body {
          overflow: hidden;
        }
      `}</style>
      <DevControls
        block={block}
        setBlock={setBlock}
        showDevImage={showDevImage}
        setShowDevImage={setShowDevImage}
        chatMessages={chatMessages}
        setChatMessages={setChatMessages}
      />
      <AnimatePresence>
        <motion.div
          key='not-detected'
          {...motionProps}
          style={{ display: isInIframe && rankImageDetails?.notLoaded ? 'block' : 'none' }}
        >
          <div id='not-detected'>
            <Center style={{ height }}>
              <div className='space-y-6 rounded-md bg-gray-300 p-4'>
                <Spin spinning>
                  <div className='flex text-center'>
                    <div className='ml-3'>
                      <h3 className='text-2xl font-medium text-gray-800'>Waiting for Dota</h3>
                      <div className='mt-2 text-lg text-gray-700'>
                        <p>Dotabod hasn&apos;t detected your game yet.</p>
                      </div>
                    </div>
                  </div>
                </Spin>
              </div>
            </Center>
          </div>
        </motion.div>

        <OverlayV2>
          <RestrictFeature feature='livePolls'>
            <PollOverlays
              pollData={pollData}
              setBetData={setBetData}
              setPollData={setPollData}
              betData={betData}
              radiantWinChance={radiantWinChance}
            />
          </RestrictFeature>

          {showMainScreenOverlay && (
            <MainScreenOverlays
              key='main-screen-overlays'
              block={block}
              wl={wl}
              rankImageDetails={rankImageDetails}
            />
          )}

          <PickScreenOverlays
            block={block}
            key='hero-blocker-class'
            rankImageDetails={rankImageDetails}
            wl={wl}
          />

          <RestrictFeature feature='lastFmOverlay'>
            <AnimatedLastFm block={block} />
          </RestrictFeature>

          <InGameOutsideCenterV2>
            <RestrictFeature feature='autoTranslate'>
              <ChatMessagesOverlay chatMessages={chatMessages} />
            </RestrictFeature>
          </InGameOutsideCenterV2>
        </OverlayV2>

        <InGameOverlays
          key='in-game-overlays'
          block={block}
          wl={wl}
          rankImageDetails={rankImageDetails}
          paused={paused}
          roshan={roshan}
          setRoshan={setRoshan}
          setAegis={setAegis}
          aegis={aegis}
          notablePlayers={notablePlayers}
        />

        {isDevMode && showDevImage && (
          <Image
            key='dev-image'
            width={width}
            height={height}
            alt={`${block.type} dev screenshot`}
            src={`/images/dev/${width && height && Math.round((width / height) * 9) === 21 ? '21-9-' : ''}${block.type === 'spectator' ? 'playing' : (block.type ?? 'main-menu')}.png`}
          />
        )}
      </AnimatePresence>
      <DevModeToggle />
    </>
  )
}

useEffect(() => {
    if (isOverlay || status === 'loading') {
      return
    }

    window._hsq = window._hsq || []
    window.hsConversationsOnReady = window.hsConversationsOnReady || []
    // Keep the widget from auto-loading before identity resolves, but preserve any
    // Identification already set on a previous run so we don't transiently drop it.
    window.hsConversationsSettings = {
      ...window.hsConversationsSettings,
      loadImmediately: false,
    }

    // Each effect run owns its own `cancelled` flag; the cleanup flips it so any
    // Queued onReady callback from a superseded run becomes a no-op.
    let cancelled = false

    const loadWith = (identity?: { email: string; token: string }) => {
      if (cancelled) {
        return
      }

      window.hsConversationsSettings = identity
        ? {
            identificationEmail: identity.email,
            identificationToken: identity.token,
            loadImmediately: false,
          }
        : { loadImmediately: false }

      const run = () => {
        if (cancelled) {
          return
        }
        // Re-identifying (login/logout without a full reload) requires resetting
        // The widget before it reloads with the new identity.
        if (loadedRef.current) {
          window.HubSpotConversations?.clear?.({ resetWidget: true })
        }
        window.HubSpotConversations?.widget?.load()
        loadedRef.current = true
      }

      if (window.HubSpotConversations) {
        run()
      } else {
        window.hsConversationsOnReady?.push(run)
      }
    }

    if (status === 'authenticated' && data?.user?.email) {
      fetch('/api/hubspot/visitor-token')
        .then((res) => (res.ok && res.status !== 204 ? res.json() : null))
        .then((payload: { email?: string; token?: string } | null) => {
          if (cancelled) {
            return
          }
          if (payload?.email && payload?.token) {
            window._hsq.push(['identify', { email: payload.email, name: data.user?.name }])
            // Identify is only transmitted to HubSpot on the next trackPageView.
            window._hsq.push(['trackPageView'])
            loadWith({ email: payload.email, token: payload.token })
          } else if (!loadedRef.current) {
            // No identity available and nothing loaded yet — still show the widget.
            loadWith()
          }
        })
        .catch(() => {
          // Don't downgrade an already-identified widget; only load if nothing has.
          if (!cancelled && !loadedRef.current) {
            loadWith()
          }
        })
    } else {
      // Anonymous visitor: load the widget without identification.
      loadWith()
    }

    return () => {
      cancelled = true
    }
  }, [isOverlay, status, data?.user?.email])

({
  userData: ssrUserData,
  subscriptionInfo: ssrSubscriptionInfo,
  username: ssrUsername,
  collection,
  heroPerformance = [],
  recentMatches = [],
}: PageContentProps = {}) => {
  const [permission, setPermission] = useState('All')
  const [enabled, setEnabled] = useState('All')
  const [searchTerm, setSearchTerm] = useState('')
  const [openCardKey, setOpenCardKey] = useState<string | null>(null)
  const router = useRouter()
  const { username } = router.query
  const { data, loading, error, notFound } = useGetSettingsByUsername()

  const shouldFetchSub = !ssrSubscriptionInfo && typeof username === 'string' && Boolean(username)
  const { data: subData, isLoading: subLoading } = useSWR<{
    isPro?: boolean
    isLifetime?: boolean
    isGracePeriodPro?: boolean
    inGracePeriod?: boolean
  }>(shouldFetchSub ? `/api/subscription/by-username?username=${username}` : null, fetcher)

  const subscriptionInfo = {
    inGracePeriod: ssrSubscriptionInfo?.inGracePeriod ?? subData?.inGracePeriod ?? false,
    isGracePeriodPro: ssrSubscriptionInfo?.isGracePeriodPro ?? subData?.isGracePeriodPro ?? false,
    isLifetime: ssrSubscriptionInfo?.isLifetime ?? subData?.isLifetime ?? false,
    isPro: ssrSubscriptionInfo?.isPro ?? subData?.isPro ?? false,
    loading: shouldFetchSub ? subLoading : false,
  }

  // Use SSR data if available, otherwise fall back to client-side data
  const finalUserData = ssrUserData || data
  const finalLoading = ssrUserData ? false : loading
  const profile = finalUserData as {
    displayName?: string | null
    name?: string
    stream_online?: boolean
    image?: string | null
    createdAt?: string
    mmr?: number
    twitchId?: string | null
    settings?: { key: string; value: unknown }[]
    error?: unknown
  }

  useEffect(() => {
    // Only redirect to 404 if username exists in query and we've finished loading (for client-side only)
    if (!ssrUserData && username && !finalLoading && (notFound || profile?.error || error)) {
