(reason: DisableReason, metadata?: Record<string, string | undefined>) => {
      switch (reason) {
        case 'TOKEN_REVOKED': {
          return {
            action: 'Reconnect your Twitch account',
            description:
              "You removed Dotabod's access to your Twitch account. Please reconnect to restore functionality.",
            severity: 'high' as const,
            title: 'App permissions revoked',
          }
        }

        case 'MANUAL_DISABLE': {
          return {
            action: 'Use !enable command to re-enable',
            description: `Dotabod was disabled by ${metadata?.disabled_by || 'a moderator'} using the ${metadata?.command || '!disable'} command.`,
            severity: 'medium' as const,
            title: 'Manually disabled',
          }
        }

        case 'STREAM_OFFLINE': {
          return {
            action: 'Start streaming to re-enable',
            description: 'This feature only works when you are streaming live on Twitch.',
            severity: 'low' as const,
            title: 'Stream is offline',
          }
        }

        case 'CHAT_PERMISSION_DENIED': {
          return {
            action:
              metadata?.drop_reason === 'followers_only_mode'
                ? 'Make Dotabod a moderator or disable followers-only mode'
                : metadata?.drop_reason === 'user_warned'
                  ? 'The Dotabod bot account needs to acknowledge its warning in your Twitch channel'
                  : metadata?.drop_reason === 'banned_phone_alias'
                    ? "Unban the Dotabod bot's phone number in your Twitch channel moderation settings"
                    : 'Check your channel settings and ensure Dotabod has proper permissions',
            description:
              metadata?.drop_reason === 'followers_only_mode'
                ? 'Dotabod cannot send messages because your channel is in followers-only mode and the bot is not a moderator.'
                : metadata?.drop_reason === 'user_warned'
                  ? 'Dotabod cannot send messages because the bot account is currently warned and must acknowledge the warning first.'
                  : metadata?.drop_reason === 'banned_phone_alias'
                    ? "Dotabod cannot send messages because the bot's phone number is banned from your channel."
                    : `Dotabod cannot send messages due to: ${metadata?.drop_reason_message || 'chat permission restrictions'}.`,
            severity: 'high' as const,
            title: 'Chat permission denied',
          }
        }

        case 'SUBSCRIPTION_INSUFFICIENT': {
          return {
            action: `Upgrade to ${metadata?.required_tier || 'Pro'}`,
            description: `This feature requires a ${metadata?.required_tier || 'Pro'} subscription. Your current tier is ${metadata?.current_tier || 'Free'}.`,
            severity: 'medium' as const,
            title: 'Subscription required',
          }
        }

        case 'API_ERROR': {
          return {
            action: 'Contact support if this persists',
            description: `Failed to communicate with ${metadata?.api_endpoint || 'external service'}: ${metadata?.error_message || 'Unknown error'}`,
            severity: 'medium' as const,
            title: 'API error occurred',
          }
        }

        case 'INVALID_TOKEN': {
          return {
            action: 'Refresh your connection in settings',
            description: 'Your Twitch authentication has expired and needs to be refreshed.',
            severity: 'high' as const,
            title: 'Authentication expired',
          }
        }

        case 'BOT_BANNED': {
          return {
            action: 'Unban the Dotabod bot in your Twitch moderation settings',
            description: 'The Dotabod bot has been banned from your Twitch channel.',
            severity: 'high' as const,
            title: 'Bot is banned',
          }
        }

        case 'ACCOUNT_SHARING': {
          return {
            action:
              'Use !clearsharing to reset, but ensure only one person has the Dotabod GSI config file',
            description: metadata?.blocked_steam32_id
              ? `Multiple people are using Dotabod GSI files for this stream. Steam account "${metadata?.account_name || 'Unknown'}" was blocked to prevent conflicts. Only the first account per stream is allowed.`
              : 'Multiple Steam accounts are sending game data to this stream. Additional accounts are blocked to prevent conflicts.',
            severity: 'high' as const,
            title: 'Multiple Steam accounts detected',
          }
        }

        default: {
          return {
            action: 'Check your settings or contact support',
            description: 'This feature has been automatically disabled.',
            severity: 'medium' as const,
            title: 'Feature disabled',
          }
        }
      }
    }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)
  if (!session?.user?.id) {
    res.status(401).json({ message: 'Unauthorized' })
    return
  }

  if (!session?.user?.role?.includes('admin')) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }

  try {
    const userId = session.user.id

    // Get gift type from query parameter or default to monthly
    const giftType = (req.query.giftType as string) || 'monthly'
    const validGiftTypes = ['monthly', 'annual', 'lifetime']

    if (!validGiftTypes.includes(giftType)) {
      res.status(400).json({ message: 'Invalid gift type. Must be monthly, annual, or lifetime' })
      return
    }

    // Get gift message from request body or use default
    const giftMessage =
      req.body?.giftMessage || 'This is a test gift message. Enjoy your subscription!'

    // Get gift quantity from request body or use default
    const giftQuantity = Number.parseInt(req.body?.giftQuantity || '1', 10)

    // Validate gift quantity
    if (Number.isNaN(giftQuantity) || giftQuantity < 1) {
      res.status(400).json({ message: 'Gift quantity must be a positive number' })
      return
    }

    // For lifetime, enforce quantity = 1
    const finalGiftQuantity = giftType === 'lifetime' ? 1 : giftQuantity

    // Check if user already has a lifetime subscription
    if (giftType === 'lifetime') {
      const existingLifetime = await prisma.subscription.findFirst({
        where: {
          OR: [
            {
              transactionType: 'LIFETIME',
            },
            {
              giftDetails: {
                giftType: 'lifetime',
              },
              isGift: true,
            },
          ],
          status: 'ACTIVE',
          userId,
        },
      })

      if (existingLifetime) {
        // For testing purposes, we'll still create the notification but add a warning
        console.warn(
          `User ${userId} already has a lifetime subscription but creating a test notification anyway`,
        )
      }
    }

    // Calculate the end date based on quantity
    // 30 days from now
    const currentPeriodEnd = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)

    // If quantity > 1, extend the period end date
    if (finalGiftQuantity > 1) {
      if (giftType === 'monthly') {
        // Add (quantity - 1) months to the end date
        currentPeriodEnd.setMonth(currentPeriodEnd.getMonth() + (finalGiftQuantity - 1))
      } else if (giftType === 'annual') {
        // Add (quantity - 1) years to the end date
        currentPeriodEnd.setFullYear(currentPeriodEnd.getFullYear() + (finalGiftQuantity - 1))
      }
    }

    // Create a test subscription with isGift flag
    const subscription = await prisma.subscription.create({
      data: {
        cancelAtPeriodEnd: false,
        currentPeriodEnd,
        isGift: true,
        status: 'ACTIVE',
        tier: 'PRO',
        transactionType: 'RECURRING',
        userId,
      },
    })

    // Create a gift subscription record
    const giftSubscription = await prisma.giftSubscription.create({
      data: {
        giftMessage,
        giftQuantity: finalGiftQuantity,
        giftType,
        senderName: 'Test Sender',
        subscriptionId: subscription.id,
      },
    })

    // Create a notification for the gift
    const notification = await prisma.notification.create({
      data: {
        giftSubscriptionId: giftSubscription.id,
        isRead: false,
        type: 'GIFT_SUBSCRIPTION',
        userId,
      },
    })

    // Get total active gift subscriptions for this user
    const activeGiftSubscriptions = await prisma.subscription.findMany({
      include: {
        giftDetails: true,
      },
      where: {
        isGift: true,
        status: 'ACTIVE',
        userId,
      },
    })

    // Calculate total gifted months
    let totalGiftedMonths = 0
    let hasLifetime = false

    for (const sub of activeGiftSubscriptions) {
      if (sub.giftDetails?.giftType === 'lifetime') {
        hasLifetime = true
        break
      }

      if (sub.giftDetails?.giftType === 'annual') {
        // Apply the gift quantity multiplier
        const quantity = sub.giftDetails.giftQuantity || 1
        totalGiftedMonths += 12 * quantity
      } else if (sub.giftDetails?.giftType === 'monthly') {
        // Apply the gift quantity multiplier
        const quantity = sub.giftDetails.giftQuantity || 1
        totalGiftedMonths += Number(quantity)
      }
    }

    res.status(200).json({
      giftSubscription,
      hasLifetime,
      message: 'Test gift notification created',
      notification,
      subscription,
      success: true,
      totalGiftedMonths: hasLifetime ? 'lifetime' : totalGiftedMonths,
    })
    return
  } catch (error) {
    console.error('Error creating test gift notification:', error)
    res.status(500).json({ error: String(error), message: 'Internal server error' })
    return
  }
}

