    loadingTimeout: 8000,
    // 5 seconds
    errorRetryInterval: 5000,
    errorRetryCount: 3,
    onErrorRetry: (_error, _key, _config, revalidate, { retryCount }) => {
      // Only retry up to 3 times
      if (retryCount >= 3) {
        return
      }

      // Retry after 5 seconds
      setTimeout(() => revalidate({ retryCount }), 5000)
    },
  })

