useCallback(async () => {
    if (!username || !LASTFM_API_KEY) {
      return
    }

    try {
      setLoading(true)
      setError(null)

      // Call Last.fm via the Next.js rewrite proxy — no serverless function invocation
      const url = `/lastfm-proxy/2.0/?method=user.getrecenttracks&user=${encodeURIComponent(username)}&api_key=${LASTFM_API_KEY}&format=json&limit=1`
      const response = await fetch(url)

      if (!response.ok) {
        setError('Error fetching Last.fm data')
        setTrack(null)
        return
      }

      const data = await response.json()
      const parsed = parseLastFmResponse(data)

      if (!parsed) {
        setError(data?.message || 'Not currently playing anything')
        setTrack(null)
        return
      }

      // Compare with previous track to avoid unnecessary rerenders
      const prev = prevTrackRef.current
      if (
        !prev ||
        prev.artist !== parsed.artist ||
        prev.title !== parsed.title ||
        prev.album !== parsed.album ||
        prev.albumArt !== parsed.albumArt ||
        prev.url !== parsed.url
      ) {
        prevTrackRef.current = parsed
        setTrack(parsed)
      }
    } catch (error) {
      console.error('Error fetching Last.fm data:', error)
      setError('Failed to fetch Last.fm data')
      setTrack(null)
    } finally {
      setLoading(false)
    }
  }, [username])

useEffect(() => {
    const handleSteamCallback = async () => {
      if (router.query['openid.ns'] && status === 'authenticated') {
        setLoading(true)
        try {
          // Send all OpenID response parameters to our server to verify
          const openIdParams = { ...router.query }

          // Verify the Steam authentication server-side
          const response = await fetch('/api/steam/validate-auth', {
            body: JSON.stringify(openIdParams),
            headers: {
              'Content-Type': 'application/json',
            },
            method: 'POST',
          })

          if (!response.ok) {
            const error = await response.json()
            throw new Error(error.message || 'Steam authentication validation failed')
          }

          const { steam32Id } = await response.json()

          if (steam32Id) {
            // Show success notification
            notification.success({
              description:
                'Your Steam account has been successfully verified and linked to your profile',
              message: 'Dotabod Verified!',
            })

            // Track successful verification
            track('steam_verification_success', { steam32Id })

            // Refresh the list of linked accounts
            const accountsResponse = await fetch('/api/steam/get-linked-account')
            if (accountsResponse.ok) {
              const data = await accountsResponse.json()

              if (data.linked) {
                setLinkedAccounts(
                  data.accounts.map((account: LinkedAccount) => ({
                    ...account,
                    loading: false,
                    profile: null,
                  })),
                )

                // Fetch player profiles for all accounts
                for (const account of data.accounts) {
                  void fetchPlayerProfile(Number.parseInt(account.steam32Id, 10))
                }
              }
            }

            // Clear query parameters from URL
            void router.replace('/verify', undefined, { shallow: true })
          } else {
            throw new Error('Invalid Steam authentication response')
          }
        } catch (error) {
          captureException(error)
          console.error('Error processing Steam authentication:', error)
          notification.error({
            description: 'There was an error verifying your Steam account. Please try again.',
            message: 'Steam Verification Failed',
          })
          track('steam_verification_error')
          void router.replace('/verify', undefined, { shallow: true })
        } finally {
          setLoading(false)
        }
      }
    }

    void handleSteamCallback()
  }, [router.query, status, router, notification, track])

