      if (!isOverflowing || !textRef.current || !containerRef.current) {
        return
      }

      const textElement = textRef.current
      const containerElement = containerRef.current
      // Slightly faster animation
      const animateDuration = textElement.scrollWidth * 0.015

      const animate = async () => {
        if (animationCancelled) {
          return
        }

        // Pause at start
        await new Promise((resolve) => setTimeout(resolve, 2000))
        if (animationCancelled) {
          return
        }

        // Scroll to end
        await controls.start({
          transition: { duration: animateDuration, ease: 'easeInOut' },
          x: containerElement.clientWidth - textElement.scrollWidth,
        })
        if (animationCancelled) {
          return
        }

        // Pause at end
        await new Promise((resolve) => setTimeout(resolve, 1500))
        if (animationCancelled) {
          return
        }

        // Scroll back to start
        await controls.start({
          transition: { duration: animateDuration, ease: 'easeInOut' },
          x: 0,
        })

        if (!animationCancelled) {
          // Repeat animation
          void animate()
        }
      }

      void animate()
    }

