({ token, account, user, profile }) {
      // Save a db lookup
      if (token.id) {
        return token
      }

      if (!user) {
        if (!token.sub) {
          throw new Error('User ID is required')
        }
        token.id = token.sub
        return token
      }

      const twitchProfile: TwitchProfile | undefined = parseTwitchProfile(profile)
      const twitchUser = user as TwitchUser

      // displayName MUST prefer the fresh OIDC `preferred_username` over
      // `twitchUser.displayName` — on returning sign-ins, `twitchUser` is the
      // existing DB row (set by NextAuth from getUserByAccount), so using it
      // first would mask a Twitch-side rename. `preferred_username` is always
      // the current rendered display name from this sign-in's id_token.
      //
      // `name` is the inverse: `preferred_username` is the *display* name
      // (uppercase/Unicode), not the lowercase login chat/Helix require. On
      // NEW sign-ins the TwitchProvider.profile() override fills
      // `twitchUser.name` with the Helix `login`. On RETURNING sign-ins it's
      // the (potentially stale) DB value — when displayName change is
      // detected below, the prisma.user.update triggers the backend's
      // UPDATE:users watcher, which calls /helix/users itself and reconciles
      // both fields.
      const newUser = {
        displayName:
          twitchProfile?.preferred_username ?? twitchUser.displayName ?? token.name ?? '',
        email: twitchProfile?.email ?? twitchUser.email,
        image: twitchProfile?.picture ?? twitchUser.image,
        name: twitchUser.name ?? twitchProfile?.preferred_username?.toLowerCase() ?? '',
      }

      const provider = await prisma.user.findFirst({
        select: {
          Account: {
            select: {
              providerAccountId: true,
              requires_refresh: true,
              scope: true,
            },
          },
          admin: {
            select: {
              role: true,
            },
          },
          bannedAt: true,
          displayName: true,
          locale: true,
        },
        where: {
          id: token.id || user.id || twitchProfile?.sub,
        },
      })

      // Hard gate: a banned user cannot acquire a JWT. NextAuth surfaces a
      // thrown error to /error?error=<message>; the error page maps
      // ACCOUNT_BANNED to a "you're banned, contact support" copy.
      if (provider?.bannedAt) {
        throw new Error('ACCOUNT_BANNED')
      }

      const isImpersonating = account?.provider === 'impersonate'

      // Check if user is logging in as a chatter by comparing scopes
      const isLoggingInAsChatter = account?.scope
        ? account.scope.split(' ').length === chatVerifyScopes.split(' ').length &&
          account.scope.split(' ').every((scope) => chatVerifyScopes.split(' ').includes(scope))
        : false

      // Check if user is logging in as a bot by comparing scopes
      const isLoggingInAsBot = account?.scope
        ? account.scope.split(' ').length === chatBotScopes.split(' ').length &&
          account.scope.split(' ').every((scope) => chatBotScopes.split(' ').includes(scope))
        : false

      const isLoggingInAsStreamer = account?.scope
        ? account.scope.split(' ').length === defaultScopes.split(' ').length &&
          account.scope.split(' ').every((scope) => defaultScopes.split(' ').includes(scope))
        : false

      const alreadyHasStreamerScopes =
        provider?.Account?.scope &&
        provider.Account.scope.split(' ').length > chatVerifyScopes.split(' ').length &&
        provider.Account.requires_refresh === false

      const getRoleFromScopes = (): 'bot' | 'user' | 'chatter' | 'admin' => {
        if (provider?.admin?.role) {
          return provider.admin.role as 'admin'
        }

        if (isLoggingInAsBot) {
          return 'bot'
        }

        // Even if they login as chatter, since they have streamer scopes, we should treat them as a user
        if (alreadyHasStreamerScopes) {
          return 'user'
        }

        if (isLoggingInAsStreamer) {
          return 'user'
        }

        if (isLoggingInAsChatter) {
          return 'chatter'
        }

        return 'user'
      }

      const roleFromScopes = getRoleFromScopes()

      let scopesToUpdate = account?.scope ?? defaultScopes
      if (roleFromScopes === 'chatter') {
        scopesToUpdate = chatVerifyScopes
      } else if (roleFromScopes === 'bot') {
        scopesToUpdate = chatBotScopes
      } else if (alreadyHasStreamerScopes && isLoggingInAsChatter) {
        // Preserve the existing streamer scopes when signing in as a chatter.
        scopesToUpdate = provider?.Account?.scope ?? defaultScopes
      }

      // Name change case. This case is further handled in the webhook utils for `twitch-events`
      if (
        !isImpersonating &&
        provider?.displayName &&
        provider.displayName !== newUser.displayName
      ) {
        await prisma.user.update({
          data: {
            displayName: newUser.displayName,
            updatedAt: new Date(),
          },
          where: {
            id: user.id,
          },
        })
      }

      const twitchId = Number(provider?.Account?.providerAccountId ?? '0')
      if (!twitchId) {
        throw new Error('Twitch ID is required')
      }

      let shouldRefresh = false
      if (account) {
        shouldRefresh = true

        if (isLoggingInAsChatter && alreadyHasStreamerScopes) {
          shouldRefresh = false
        }

        if (isImpersonating) {
          shouldRefresh = false
        }
      }

      if (shouldRefresh && account) {
        // Set requires_refresh to false if the user is logging in
        // Because this new token will be the fresh one we needed
        await prisma.account.update({
          data: {
            access_token: account.access_token,
            expires_at: account.expires_at,
            refresh_token: account.refresh_token,
            requires_refresh: false,
            scope: account.scope,
            updatedAt: new Date(),
          },
          where: {
            provider_providerAccountId: {
              provider: account.provider,
              providerAccountId: account.providerAccountId,
            },
          },
        })
      }

      const result = {
        email: newUser.email,
        id: user.id,
        image: newUser.image || '',
        isImpersonating,
        locale: provider?.locale,
        name: newUser.displayName || newUser.name,
        role: roleFromScopes,
        scope: scopesToUpdate,
        twitchId: String(twitchId),
      }

      return result as JWT
    }

async () => {
        // Find the subscription that references this invoice
        const subscription = await tx.subscription.findFirst({
          where: {
            metadata: {
              equals: invoice.id,
              path: ['renewalInvoiceId'],
            },
            stripeCustomerId: customerId,
          },
        })

        if (!subscription) {
          console.log(`No subscription found with renewalInvoiceId: ${invoice.id}`)
          // If we have an overdue or uncollectible invoice but no subscription with this invoice ID,
          // Try to find by customer ID (for current period invoices)
          if (
            invoice.status === 'uncollectible' ||
            invoice.status === 'void' ||
            (invoice.status === 'open' &&
              invoice.due_date &&
              new Date(invoice.due_date * 1000) < new Date())
          ) {
            const activeSubscription = await tx.subscription.findFirst({
              where: {
                status: { in: [SubscriptionStatus.ACTIVE, SubscriptionStatus.PAST_DUE] },
                stripeCustomerId: customerId,
                userId,
              },
            })

            if (activeSubscription) {
              console.log(
                `Found active subscription ${activeSubscription.id} for customer ${customerId}`,
              )
              // Mark as past due or cancelled depending on the situation
              const newStatus =
                invoice.status === 'uncollectible' || invoice.status === 'void'
                  ? SubscriptionStatus.CANCELED
                  : SubscriptionStatus.PAST_DUE

              await tx.subscription.update({
                data: {
                  metadata: {
                    ...toMetadataObject(activeSubscription.metadata),
                    lastInvoiceStatus: invoice.status,
                    lastUnpaidInvoiceId: invoice.id,
                  },
                  status: newStatus,
                  updatedAt: new Date(),
                },
                where: { id: activeSubscription.id },
              })

              console.log(`Updated subscription ${activeSubscription.id} status to ${newStatus}`)
              return true
            }
          }

          return false
        }

        // Only process paid invoices
        if (invoice.status === 'paid') {
          console.log(
            `Processing paid crypto invoice ${invoice.id} for subscription ${subscription.id}`,
          )

          // Check if this is a lifetime subscription - lifetime subscriptions should never generate renewal invoices
          if (subscription.transactionType === 'LIFETIME') {
            console.log(
              `Skipping renewal invoice creation for lifetime subscription ${subscription.id}`,
            )
            return true
          }

          // Get price ID and period from the subscription
          const priceId = subscription.stripePriceId
          // Extract and use metadata safely
          const metadata = (subscription.metadata as Record<string, unknown>) || {}
          const pricePeriod = (metadata.priceType as string) || 'monthly'

          if (!priceId) {
            console.error(`Missing priceId in subscription: ${subscription.id}`)
            return false
          }

          // Calculate the new period end date
          const isAnnual = pricePeriod === 'annual'

          // Handle the Date properly, considering currentPeriodEnd could be a Date object or string
          let baseDate: Date
          if (subscription.currentPeriodEnd) {
            // Handle if it's already a Date or needs to be converted from string
            baseDate =
              subscription.currentPeriodEnd instanceof Date
                ? subscription.currentPeriodEnd
                : new Date(subscription.currentPeriodEnd)
          } else {
            baseDate = new Date()
          }

          const newPeriodEnd = new Date(baseDate)

          if (isAnnual) {
            newPeriodEnd.setFullYear(newPeriodEnd.getFullYear() + 1)
          } else {
            // Monthly
            newPeriodEnd.setMonth(newPeriodEnd.getMonth() + 1)
          }

          // Create a new draft invoice for the next period
          const renewalDate = new Date(newPeriodEnd)
          // Set the invoice date to 7 days before the period ends
          renewalDate.setDate(renewalDate.getDate() - 7)

          // Calculate the period end date based on the price period
          const periodEnd = new Date()
          if (isAnnual) {
            periodEnd.setFullYear(periodEnd.getFullYear() + 1)
          } else {
            // Monthly
            periodEnd.setMonth(periodEnd.getMonth() + 1)
          }

          try {
            // Create a new draft invoice for the next period
            // Use type assertion to fix customerId type issue
            const params: Stripe.InvoiceCreateParams = {
              // Enable automatic advancement so Stripe handles finalization
              auto_advance: true,
              automatically_finalizes_at: Math.floor(renewalDate.getTime() / 1000),
              collection_method: 'send_invoice',
              customer: customerId,
              description: `Crypto Dotabod Pro ${pricePeriod.charAt(0).toUpperCase() + pricePeriod.slice(1)} subscription`,
              // Due date 7 days after finalization date
              due_date: Math.floor((renewalDate.getTime() + 7 * 24 * 60 * 60 * 1000) / 1000),
              metadata: {
                isCryptoPayment: 'true',
                isRenewalInvoice: 'true',
                previousInvoiceId: invoice.id ?? '',
                pricePeriod,
                userId,
              },
            }

            const newInvoice = await stripe.invoices.create(params)

            // Fetch the price details from Stripe
            const price = await stripe.prices.retrieve(priceId)
            if (!price.unit_amount) {
              throw new Error('Price unit amount is not set')
            }

            // Add the line item for the price
            await stripe.invoiceItems.create({
              amount: price.unit_amount,
              customer: customerId,
              description: `Crypto Dotabod Pro ${pricePeriod.charAt(0).toUpperCase() + pricePeriod.slice(1)} subscription`,
              invoice: newInvoice.id,
            })

            console.log(
              `Created new renewal draft invoice ${newInvoice.id} for next crypto payment period`,
            )

            // Update the subscription with the new period end and invoice ID
            await tx.subscription.update({
              data: {
                // Will expire at the end of the period
                cancelAtPeriodEnd: true,
                currentPeriodEnd: newPeriodEnd,
                metadata: {
                  ...toMetadataObject(subscription.metadata),
                  previousRenewalInvoiceId: invoice.id ?? '',
                  priceType: pricePeriod,
                  renewalDueDate: renewalDate.toISOString(),
                  renewalInvoiceId: newInvoice.id,
                },
                status: SubscriptionStatus.ACTIVE,
                updatedAt: new Date(),
              },
              where: { id: subscription.id },
            })

            console.log(
              `Updated crypto subscription ${subscription.id} with new period end ${newPeriodEnd.toISOString()} and new invoice ID ${newInvoice.id}`,
            )

            return true
          } catch (error) {
            console.error('Failed to create next crypto renewal invoice:', error)

            // Still update the subscription period
            await tx.subscription.update({
              data: {
                cancelAtPeriodEnd: true,
                currentPeriodEnd: newPeriodEnd,
                metadata: {
                  ...toMetadataObject(subscription.metadata),
                  renewalError: 'true',
                },
                status: SubscriptionStatus.ACTIVE,
                updatedAt: new Date(),
              },
              where: { id: subscription.id },
            })

            return false
          }
        } else if (invoice.status === 'uncollectible' || invoice.status === 'void') {
          // Mark the subscription as inactive if the invoice is void or uncollectible
          await tx.subscription.update({
            data: {
              metadata: {
                ...toMetadataObject(subscription.metadata),
                cancellationReason: 'invoice_uncollectible',
                lastUnpaidInvoiceId: invoice.id,
              },
              status: SubscriptionStatus.CANCELED,
              updatedAt: new Date(),
            },
            where: { id: subscription.id },
          })

          console.log(
            `Marked subscription ${subscription.id} as CANCELED due to uncollectible/void invoice`,
          )
          return true
        } else if (
          invoice.status === 'open' &&
          invoice.due_date &&
          new Date(invoice.due_date * 1000) < new Date()
        ) {
          // Invoice is overdue (open but past due date)
          await tx.subscription.update({
            data: {
              metadata: {
                ...toMetadataObject(subscription.metadata),
                lastOverdueInvoiceId: invoice.id,
              },
              status: SubscriptionStatus.PAST_DUE,
              updatedAt: new Date(),
            },
            where: { id: subscription.id },
          })

          console.log(`Marked subscription ${subscription.id} as PAST_DUE due to overdue invoice`)
          return true
        }

        return true
      }

