async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    res.status(405).json({ error: 'Method not allowed' })
    return
  }

  try {
    // Authenticate user
    const session = await getServerSession(req, res, authOptions)
    if (!session?.user) {
      res.status(401).json({ error: 'Unauthorized' })
      return
    }

    const { invoiceId } = req.query

    if (!invoiceId || typeof invoiceId !== 'string') {
      res.status(400).json({ error: 'Invoice ID is required' })
      return
    }

    // Get Stripe invoice to verify user ownership
    let invoice = await stripe.invoices.retrieve(invoiceId)
    if (invoice.metadata?.userId !== session.user.id) {
      res.status(403).json({ error: 'Access denied' })
      return
    }

    // Get OpenNode charge status
    const openNodeCharge = await prisma.openNodeCharge.findUnique({
      where: { stripeInvoiceId: invoiceId },
    })

    if (!openNodeCharge) {
      res.status(404).json({ error: 'Payment not found' })
      return
    }

    // Get fresh status from OpenNode
    const chargeStatus = await getOpenNodeChargeStatus(openNodeCharge.openNodeChargeId)

    // Update local status if different
    if (chargeStatus && chargeStatus.status !== openNodeCharge.status) {
      await prisma.openNodeCharge.update({
        data: {
          status: chargeStatus.status,
          updatedAt: new Date(),
        },
        where: { id: openNodeCharge.id },
      })
    }

    const currentStatus = chargeStatus?.status || openNodeCharge.status

    if (isOpenNodePaymentConfirmed(currentStatus)) {
      try {
        await processConfirmedOpenNodePayment(
          { ...openNodeCharge, status: currentStatus },
          currentStatus,
        )
        invoice = await stripe.invoices.retrieve(invoiceId)
      } catch (error) {
        console.error('Confirmed OpenNode payment activation failed:', error)
        res.status(500).json({
          error: 'Payment confirmed, but subscription activation failed. Please contact support.',
        })
        return
      }
    }

    const invoiceAmount = (invoice.total || invoice.amount_due || 0) / 100

    // Return user-friendly status information
    res.status(200).json({
      amount: invoiceAmount || openNodeCharge.amount,
      chargeId: openNodeCharge.openNodeChargeId,
      createdAt: openNodeCharge.createdAt,
      currency: invoice.currency || openNodeCharge.currency,
      invoice: {
        amount: invoice.amount_due ? invoice.amount_due / 100 : 0,
        currency: invoice.currency,
        id: invoice.id,
        number: invoice.number,
        status: invoice.status,
      },
      invoiceId,
      status: currentStatus,
      statusInfo: getStatusInfo(currentStatus),
    })
  } catch (error) {
    console.error('Payment status check failed:', error)
    res.status(500).json({ error: 'Failed to check payment status' })
    return
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const session = await getServerSession(req, res, authOptions)
  if (!session?.user?.role?.includes('admin')) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }

  const { id } = req.query

  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid ID' })
    return
  }

  // GET a single scheduled message with delivery stats
  if (req.method === 'GET') {
    const scheduledMessage = await prisma.scheduledMessage.findUnique({
      include: {
        user: {
          select: {
            email: true,
            id: true,
            name: true,
          },
        },
      },
      where: { id },
    })

    if (!scheduledMessage) {
      res.status(404).json({ error: 'Scheduled message not found' })
      return
    }

    // Get delivery stats
    const deliveryStats = await prisma.messageDelivery.groupBy({
      _count: {
        status: true,
      },
      by: ['status'],
      where: {
        scheduledMessageId: id,
      },
    })

    const stats = {
      cancelled: 0,
      delivered: 0,
      pending: 0,
    }

    for (const stat of deliveryStats) {
      stats[stat.status as keyof typeof stats] = Number(stat._count.status)
    }

    // Get total user count for percentage calculations
    const totalUsers = await prisma.user.count()
    const targetUserCount = scheduledMessage.isForAllUsers ? totalUsers : 1

    res.status(200).json({
      ...scheduledMessage,
      deliveryStats: {
        ...stats,
        cancelledPercent: Math.round((stats.cancelled / targetUserCount) * 100),
        deliveredPercent: Math.round((stats.delivered / targetUserCount) * 100),
        pendingPercent: Math.round((stats.pending / targetUserCount) * 100),
        totalTargetUsers: targetUserCount,
      },
    })
    return
  }

  // UPDATE a scheduled message
  if (req.method === 'PUT') {
    const { message, sendAt, userId, isForAllUsers } = req.body

    if (!message && !sendAt && userId === undefined && isForAllUsers === undefined) {
      res.status(400).json({ error: 'No fields to update' })
      return
    }

    const existingMessage = await prisma.scheduledMessage.findUnique({
      where: { id },
    })

    if (!existingMessage) {
      res.status(404).json({ error: 'Scheduled message not found' })
      return
    }

    // Don't allow editing messages that have already been sent
    if (existingMessage.status === 'DELIVERED') {
      res.status(400).json({ error: 'Cannot edit a message that has already been sent' })
      return
    }

    const updateData: Record<string, unknown> = {}
    if (message) {
      updateData.message = message
    }
    if (sendAt) {
      updateData.sendAt = new Date(sendAt)
    }

    // Handle the isForAllUsers and userId logic
    if (isForAllUsers !== undefined) {
      updateData.isForAllUsers = isForAllUsers
      if (isForAllUsers) {
        updateData.userId = null
      } else if (userId) {
        updateData.userId = userId
      }
    } else if (userId !== undefined) {
      updateData.userId = userId
      updateData.isForAllUsers = false
    }

    updateData.updatedAt = new Date()

    const updatedMessage = await prisma.scheduledMessage.update({
      data: updateData,
      where: { id },
    })

    res.status(200).json(updatedMessage)
    return
  }

  // DELETE a scheduled message
  if (req.method === 'DELETE') {
    const existingMessage = await prisma.scheduledMessage.findUnique({
      where: { id },
    })

    if (!existingMessage) {
      res.status(404).json({ error: 'Scheduled message not found' })
      return
    }

    // If the message is pending, we can delete it completely
    if (existingMessage.status === 'PENDING') {
      await prisma.scheduledMessage.delete({
        where: { id },
      })
    } else {
      // If the message is already being processed, mark it and its pending
      // deliveries as cancelled atomically.
      await prisma.$transaction(async (tx) => {
        await tx.scheduledMessage.update({
          data: { status: 'CANCELLED', updatedAt: new Date() },
          where: { id },
        })

        await tx.messageDelivery.updateMany({
          data: { status: 'CANCELLED', updatedAt: new Date() },
          where: {
            scheduledMessageId: id,
            status: 'PENDING',
          },
        })
      })
    }

    res.status(200).json({ success: true })
    return
  }

  res.status(405).json({ error: 'Method not allowed' })
}

